const makeInitials = (name) => name
  .replace(/\([^)]*\)/g, '')
  .split(/\s+/)
  .filter(Boolean)
  .slice(0, 2)
  .map((word) => word[0])
  .join('')
  .toUpperCase();

export const nigerianBanks = bankNames.map(([name, domain]) => ({
  name,
  domain,
  logo: `https://logo.clearbit.com/${domain}`,
  logoFallback: `https://www.google.com/s2/favicons?domain=${domain}&sz=128`,
  initials: makeInitials(name),
}));
